SELECT analytics_order_facts.region, COUNT(DISTINCT analytics_order_facts.order_id) AS order_count FROM analytics_order_facts WHERE analytics_order_facts.year IN (2023, 2024) AND analytics_order_facts.channel = 'marketplace' AND analytics_order_facts.customer_segment = 'education' AND analytics_order_facts.category = 'category_07' GROUP BY analytics_order_facts.region ORDER BY analytics_order_facts.region ASC LIMIT 24
